class Solution {
public:
    int minimumTime(std::vector<int>& hens, std::vector<int>& grains) {
        std::sort(hens.begin(), hens.end());
        std::sort(grains.begin(), grains.end());
        int m = grains.size();
        auto check = [&](long long t) -> bool {
            int g_idx = 0;
            for (int h : hens) {
                if (g_idx == m) break;
                long long max_right = 0;
                if (grains[g_idx] < h) {
                    long long d = h - grains[g_idx];
                    if (d > t) return false;
                    max_right = std::max((long long)h + (t - 2 * d), (long long)h + (t - d) / 2);
                } else {
                    max_right = (long long)h + t;
                }
                while (g_idx < m && grains[g_idx] <= max_right) {
                    g_idx++;
                }
            }
            return g_idx == m;
        };
        long long low = 0;
        long long high = 2LL * (std::max(hens.back(), grains.back()) - std::min(hens.front(), grains.front()));
        while (low < high) {
            long long mid = low + (high - low) / 2;
            if (check(mid)) high = mid;
            else low = mid + 1;
        }
        return low;
    }
};

class Solution {
    public int minimumTime(int[] hens, int[] grains) {
        java.util.Arrays.sort(hens);
        java.util.Arrays.sort(grains);
        int m = grains.length;
        long low = 0;
        long high = 2L * (Math.max(hens[hens.length - 1], grains[m - 1]) - Math.min(hens[0], grains[0]));
        while (low < high) {
            long mid = low + (high - low) / 2;
            int gIdx = 0;
            for (int h : hens) {
                if (gIdx == m) break;
                long maxRight;
                if (grains[gIdx] < h) {
                    long d = h - grains[gIdx];
                    if (d > mid) continue;
                    maxRight = Math.max((long) h + (mid - 2 * d), (long) h + (mid - d) / 2);
                } else {
                    maxRight = (long) h + mid;
                }
                while (gIdx < m && grains[gIdx] <= maxRight) {
                    gIdx++;
                }
            }
            if (gIdx == m) high = mid;
            else low = mid + 1;
        }
        return (int) low;
    }
}

var minimumTime = function(hens, grains) {
    hens.sort((a, b) => a - b);
    grains.sort((a, b) => a - b);
    const m = grains.length;
    let low = 0;
    let high = 2 * (Math.max(hens[hens.length - 1], grains[m - 1]) - Math.min(hens[0], grains[0]));
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        let gIdx = 0;
        for (const h of hens) {
            if (gIdx === m) break;
            let maxRight;
            if (grains[gIdx] < h) {
                const d = h - grains[gIdx];
                if (d > mid) continue;
                maxRight = Math.max(h + (mid - 2 * d), h + Math.floor((mid - d) / 2));
            } else {
                maxRight = h + mid;
            }
            while (gIdx < m && grains[gIdx] <= maxRight) {
                gIdx++;
            }
        }
        if (gIdx === m) high = mid;
        else low = mid + 1;
    }
    return low;
};
